content.content:
  v_has_booking boolean := false;
  v_has_deposit boolean := false;
BEGIN
  -- Load conversation ownership
  SELECT studio_id, client_id
  INTO   v_studio_id, v_client_id
  FROM   conversations
  WHERE  id = p_conversation_id;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- Load body of most recent inbound message in this conversation
  SELECT body
  INTO   v_body
  FROM   client_communications
  WHERE  conversation_id = p_conversation_id
    AND  direction       = 'inbound'
  ORDER BY COALESCE(sent_at, created_at) DESC
  LIMIT 1;

  -- ── Rule 1: no client attached → new unmatched sender → inquiry ────────────
  IF v_client_id IS NULL THEN
    v_tag := 'inquiry';

  -- ── Rule 2: rescheduling keywords ──────────────────────────────────────────
  ELSIF v_body ILIKE ANY (ARRAY[
      '%reschedule%', '%move%', '%change%', '%switch%', '%shift%'
    ]) THEN
    v_tag := 'rescheduling';

  -- ── Rule 3: pricing keywords ────────────────────────────────────────────────
  ELSIF v_body ILIKE ANY (ARRAY[
      '%price%', '%how much%', '%quote%', '%cost%', '%rate%'
    ]) THEN
    v_tag := 'pricing';

  ELSE
    -- ── Rule 4: upcoming booking within 7 days ────────────────────────────────
    SELECT EXISTS (
      SELECT 1
      FROM   bookings b
      WHERE  b.client_id  = v_client_id
        AND  b.studio_id  = v_studio_id
        AND  b.scheduled_at >= now()
        AND  b.scheduled_at <  now() + interval '7 days'
        AND  b.status NOT IN ('cancelled', 'no_show')
    )
    INTO v_has_booking;

    IF v_has_booking THEN
      v_tag := 'booking';
    ELSE
      -- ── Rule 5: deposit paid in last 24h (if payments table accessible) ────
      BEGIN
        SELECT EXISTS (
          SELECT 1
          FROM   payments p
          WHERE  p.client_id  = v_client_id
            AND  p.studio_id  = v_studio_id
            AND  p.status     = 'succeeded'
            AND  p.metadata->>'kind' = 'deposit_paid'
            AND  p.succeeded_at >= now() - interval '24 hours'
        )
        INTO v_has_deposit;
      EXCEPTION
        WHEN undefined_table THEN
          v_has_deposit := false;
      END;

      IF v_has_deposit THEN
        v_tag := 'deposit_paid';
      ELSE
        -- ── Rule 6: known client, no other signal → client ──────────────────
        v_tag := 'client';
      END IF;
    END IF;
  END IF;

  -- Persist the resolved tag
  UPDATE conversations
  SET    triage_tag = v_tag,
         updated_at = now()
  WHERE  id = p_conversation_id;

  RETURN v_tag;
END;
$$;

-- ============================================================
-- 6. FUNCTION enqueue_auto_reply
--    Renders a template for a matched auto-reply rule and inserts
--    a queued outbound client_communications row.
--    Returns the new comm id, or NULL if cooldown is still active.
--    Worker (send-sms / send-email) picks up the queued row.
--    SECURITY DEFINER: runs as owner so INSERT into
--    client_communications bypasses row-level RLS for auto sends.
-- ============================================================

CREATE OR REPLACE FUNCTION enqueue_auto_reply(
  p_conversation_id uuid,
  p_rule_id         uuid
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_rule            auto_reply_rules%ROWTYPE;
  v_template        message_templates%ROWTYPE;
  v_conv            conversations%ROWTYPE;
  v_studio_name     text;
  v_client_fname    text;
  v_booking_link    text;
  v_rendered_body   text;
  v_channel         text;
  v_new_comm_id     uuid;
BEGIN
  -- Load rule
  SELECT * INTO v_rule FROM auto_reply_rules WHERE id = p_rule_id;
  IF NOT FOUND OR NOT v_rule.enabled THEN
    RETURN NULL;
  END IF;

  -- Load template
  SELECT * INTO v_template FROM message_templates WHERE id = v_rule.template_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- Load conversation
  SELECT * INTO v_conv FROM conversations WHERE id = p_conversation_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- Cooldown check: skip if auto-reply was sent within cooldown window
  IF v_conv.last_auto_reply_at IS NOT NULL
    AND v_conv.last_auto_reply_at > now() - (v_rule.cooldown_minutes * interval '1 minute')
  THEN
    RETURN NULL;
  END IF;

  -- Resolve token values — use '' if data unavailable (no error)
  SELECT COALESCE(s.name, '')
  INTO   v_studio_name
  FROM   studios s
  WHERE  s.id = v_conv.studio_id;

  IF v_conv.client_id IS NOT NULL THEN
    SELECT COALESCE(c.first_name, '')
    INTO   v_client_fname
    FROM   clients c
    WHERE  c.id = v_conv.client_id;
  ELSE
    v_client_fname := '';
  END IF;

  -- booking_link: construct from studio slug (clients table has no booking_link column)
  SELECT COALESCE('/book/' || s.slug, '')
  INTO   v_booking_link
  FROM   studios s
  WHERE  s.id = v_conv.studio_id;

  -- Render template body — replace known tokens
  v_rendered_body := REPLACE(v_template.body, '{{studio_name}}',       COALESCE(v_studio_name, ''));
  v_rendered_body := REPLACE(v_rendered_body, '{{client_first_name}}', COALESCE(v_client_fname, ''));
  v_rendered_body := REPLACE(v_rendered_body, '{{booking_link}}',      COALESCE(v_booking_link, ''));

  -- Determine channel: map 'voice' conversations to 'sms' for outbound reply
  v_channel := CASE
    WHEN v_conv.channel = 'voice' THEN 'sms'
    WHEN v_conv.channel IN ('sms', 'email') THEN v_conv.channel
    ELSE 'sms'   -- fallback for instagram / facebook stubs
  END;

  -- Insert outbound queued comm
  INSERT INTO client_communications (
    studio_id,
    client_id,
    conversation_id,
    channel,
    direction,
    status,
    body,
    is_internal_note,
    metadata
  )
  VALUES (
    v_conv.studio_id,
    v_conv.client_id,
    p_conversation_id,
    v_channel,
    'outbound',
    'queued',
    v_rendered_body,
    false,
    jsonb_build_object(
      'auto_reply',  true,
      'rule_id',     p_rule_id::text,
      'template_id', v_rule.template_id::text,
      'tone',        v_rule.tone
    )
  )
  RETURNING id INTO v_new_comm_id;

  -- Stamp the cooldown timestamp on the conversation
  UPDATE conversations
  SET    last_auto_reply_at = now(),
         updated_at         = now()
  WHERE  id = p_conversation_id;

  RETURN v_new_comm_id;
END;
$$;

