/**
 * send-scheduled-message BullMQ worker.
 *
 * Consumes 'send-scheduled-message' jobs from the inkos-jobs queue.
 * Job payload: { commId: string; studioId: string }
 *   commId   — client_communications.id with status='queued' + scheduled_for set
 *   studioId — logging context + studio phone number lookup
 *
 * Dispatches via:
 *   - channel='sms'   → Twilio
 *   - channel='email' → Resend
 *
 * Retry strategy: 3 attempts, exponential backoff (1s, 5s, 25s).
 * Idempotent: skips rows already in a terminal state (sent/delivered/failed).
 */

import { Worker } from 'bullmq'
import { Twilio } from 'twilio'
import { Resend } from 'resend'
import { supabase } from '../lib/supabase'
import { logger } from '../lib/logger'
import { workerEnv } from '../lib/env'

const QUEUE_NAME = 'inkos-jobs'
const JOB_NAME = 'send-scheduled-message'

// ─── Payload type ─────────────────────────────────────────────────────────────

interface SendScheduledMessagePayload {
  commId: string
  studioId: string
}

function isValidPayload(data: unknown): data is SendScheduledMessagePayload {
  return (
    typeof data === 'object' &&
    data !== null &&
    typeof (data as Record<string, unknown>)['commId'] === 'string' &&
    typeof (data as Record<string, unknown>)['studioId'] === 'string'
  )
}

// ─── Twilio client (lazy) ─────────────────────────────────────────────────────

let _twilio: Twilio | null = null

function getTwilioClient(): Twilio | null {
  if (!workerEnv.TWILIO_ACCOUNT_SID || !workerEnv.TWILIO_AUTH_TOKEN) return null
  if (!_twilio) {
    _twilio = new Twilio(workerEnv.TWILIO_ACCOUNT_SID, workerEnv.TWILIO_AUTH_TOKEN)
  }
  return _twilio
}

// ─── Resend client (lazy) ─────────────────────────────────────────────────────

let _resend: Resend | null = null

function getResendClient(): Resend | null {
  if (!workerEnv.RESEND_API_KEY) return null
  if (!_resend) {
    _resend = new Resend(workerEnv.RESEND_API_KEY)
  }
  return _resend
}

// ─── Worker ───────────────────────────────────────────────────────────────────

export function createSendScheduledMessageWorker() {
  const worker = new Worker(
    QUEUE_NAME,
    async (job) => {
      if (job.name !== JOB_NAME) return

      if (!isValidPayload(job.data)) {
        logger.error({ jobId: job.id, data: job.data }, 'send-scheduled-message: invalid payload — skipping')
        return
      }

      const { commId, studioId } = job.data
      const workerLog = logger.child({ jobId: job.id, commId, studioId })
      workerLog.info('send-scheduled-message: processing')

      // ── 1. Fetch comm row ─────────────────────────────────────────────────
      const { data: comm, error: commErr } = await supabase
        .from('client_communications')
        .select('id, status, body, subject, client_id, studio_id, channel, scheduled_for, is_internal_note')
        .eq('id', commId)
        .single()

      if (commErr || !comm) {
        workerLog.error({ err: commErr }, 'send-scheduled-message: comm row not found')
        throw new Error(`comm row not found: ${commId}`)
      }

      // Internal notes are never dispatched
      if (comm.is_internal_note) {
        workerLog.info('send-scheduled-message: comm is internal note — skipping dispatch')
        return
      }

      // ── 2. Idempotency guard ──────────────────────────────────────────────
      const terminalStatuses = ['sent', 'delivered', 'failed', 'bounced'] as const
      if (terminalStatuses.includes(comm.status as typeof terminalStatuses[number])) {
        workerLog.info({ status: comm.status }, 'send-scheduled-message: already terminal — skipping')
        return
      }

      // ── 3. Defensive: check scheduled_for <= now() ────────────────────────
      if (comm.scheduled_for) {
        const scheduledAt = new Date(comm.scheduled_for).getTime()
        if (scheduledAt > Date.now() + 5_000) {
          // More than 5s in the future — re-queue with remaining delay
          const remainingMs = scheduledAt - Date.now()
          workerLog.warn({ scheduledFor: comm.scheduled_for, remainingMs }, 'send-scheduled-message: too early — re-queuing')
          throw new Error(`Scheduled time not reached yet (${remainingMs}ms remaining)`)
        }
      }

      // ── 4. Dispatch by channel ────────────────────────────────────────────
      if (comm.channel === 'sms') {
        await dispatchSms(comm, studioId, workerLog)
      } else if (comm.channel === 'email') {
        await dispatchEmail(comm, studioId, workerLog)
      } else {
        workerLog.warn({ channel: comm.channel }, 'send-scheduled-message: unsupported channel — skipping')
        await supabase
          .from('client_communications')
          .update({ status: 'failed', error: `Unsupported channel: ${comm.channel}`, updated_at: new Date().toISOString() })
          .eq('id', commId)
      }
    },
    {
      connection: {
        url: workerEnv.REDIS_URL,
        maxRetriesPerRequest: null,
      },
      concurrency: 5,
      // 3 attempts: 1s → 5s → 25s (exponential, base 1000ms)
    },
  )

  worker.on('completed', (job) => {
    logger.info({ jobId: job.id }, 'send-scheduled-message: completed')
  })

  worker.on('failed', (job, err) => {
    logger.error({ jobId: job?.id, err }, 'send-scheduled-message: failed')
  })

  worker.on('error', (err) => {
    logger.error({ err }, 'send-scheduled-message: worker error')
  })

  return worker
}

// ─── dispatchSms ──────────────────────────────────────────────────────────────

async function dispatchSms(
  comm: { id: string; body: string; client_id: string; studio_id: string },
  studioId: string,
  workerLog: ReturnType<typeof logger.child>,
): Promise<void> {
  const twilioClient = getTwilioClient()
  if (!twilioClient) {
    workerLog.warn('send-scheduled-message: Twilio not configured — marking failed')
    await supabase
      .from('client_communications')
      .update({ status: 'failed', error: 'Twilio not configured', updated_at: new Date().toISOString() })
      .eq('id', comm.id)
    return
  }

  // Resolve client phone
  const { data: client, error: clientErr } = await supabase
    .from('clients')
    .select('phone')
    .eq('id', comm.client_id)
    .single()

  if (clientErr || !client?.phone) {
    workerLog.warn('send-scheduled-message: client has no phone — marking failed')
    await supabase
      .from('client_communications')
      .update({ status: 'failed', error: 'Client has no phone number', updated_at: new Date().toISOString() })
      .eq('id', comm.id)
    return
  }

  // Resolve studio From number
  const { data: studio } = await supabase
    .from('studios')
    .select('twilio_phone_number')
    .eq('id', studioId)
    .single()

  const fromNumber = studio?.twilio_phone_number ?? workerEnv.TWILIO_PHONE_NUMBER

  if (!fromNumber) {
    workerLog.error('send-scheduled-message: no From number available')
    await supabase
      .from('client_communications')
      .update({ status: 'failed', error: 'No Twilio From number configured', updated_at: new Date().toISOString() })
      .eq('id', comm.id)
    return
  }

  try {
    const message = await twilioClient.messages.create({
      from: fromNumber,
      to: client.phone,
      body: comm.body,
    })

    await supabase
      .from('client_communications')
      .update({
        status: 'sent',
        provider_message_id: message.sid,
        sent_at: new Date().toISOString(),
        error: null,
        updated_at: new Date().toISOString(),
      })
      .eq('id', comm.id)

    workerLog.info({ sid: message.sid }, 'send-scheduled-message: SMS sent')
  } catch (err: unknown) {
    const errMsg = err instanceof Error ? err.message : String(err)
    workerLog.error({ err }, 'send-scheduled-message: Twilio send failed')
    await supabase
      .from('client_communications')
      .update({ status: 'failed', error: errMsg, updated_at: new Date().toISOString() })
      .eq('id', comm.id)
    throw err
  }
}

// ─── dispatchEmail ────────────────────────────────────────────────────────────

async function dispatchEmail(
  comm: { id: string; body: string; subject: string | null; client_id: string; studio_id: string },
  _studioId: string,
  workerLog: ReturnType<typeof logger.child>,
): Promise<void> {
  const resend = getResendClient()
  if (!resend) {
    workerLog.warn('send-scheduled-message: Resend not configured — marking failed')
    await supabase
      .from('client_communications')
      .update({ status: 'failed', error: 'Resend not configured', updated_at: new Date().toISOString() })
      .eq('id', comm.id)
    return
  }

  // Resolve client email
  const { data: client, error: clientErr } = await supabase
    .from('clients')
    .select('email, first_name, last_name')
    .eq('id', comm.client_id)
    .single()

  if (clientErr || !client?.email) {
    workerLog.warn('send-scheduled-message: client has no email — marking failed')
    await supabase
      .from('client_communications')
      .update({ status: 'failed', error: 'Client has no email address', updated_at: new Date().toISOString() })
      .eq('id', comm.id)
    return
  }

  try {
    const { error: sendErr } = await resend.emails.send({
      from: workerEnv.RESEND_FROM_EMAIL,
      to: client.email,
      replyTo: workerEnv.RESEND_REPLY_TO,
      subject: comm.subject ?? '(no subject)',
      text: comm.body,
    })

    if (sendErr) {
      throw new Error(sendErr.message)
    }

    await supabase
      .from('client_communications')
      .update({
        status: 'sent',
        sent_at: new Date().toISOString(),
        error: null,
        updated_at: new Date().toISOString(),
      })
      .eq('id', comm.id)

    workerLog.info({ to: client.email }, 'send-scheduled-message: email sent')
  } catch (err: unknown) {
    const errMsg = err instanceof Error ? err.message : String(err)
    workerLog.error({ err }, 'send-scheduled-message: Resend send failed')
    await supabase
      .from('client_communications')
      .update({ status: 'failed', error: errMsg, updated_at: new Date().toISOString() })
      .eq('id', comm.id)
    throw err
  }
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import {
  listConversations,
  getConversation,
  getConversationMessages,
  getConversationContext,
  getChannelUnreadCounts,
  listMessageTemplates,
  type ListConversationsFilters,
  type ConversationContext,
} from '@/lib/messaging/queries'
import { markConversationRead } from '@/lib/messaging/mutations'
import { generateSmartReplies } from '@/lib/messaging/triage'
import { MessagesShell } from '@/components/messages/MessagesShell'

export const metadata: Metadata = {
  title: 'Messages — InkOS',
}

// Next 16 — searchParams must be awaited
interface SearchParams {
  c?: string
  channel?: string
  filter?: string
  q?: string
}

interface StudioMember {
  id: string
  user_id: string
  display_name?: string | null | undefined
  role: string
}

export default async function MessagesPage({
  searchParams,
}: {
  searchParams: Promise<SearchParams>
}) {
  let studioId: string

  try {
    const ctx = await getActiveStudio()
    studioId = ctx.studioId
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  const params = await searchParams
  const activeConversationId = params.c ?? null
  const channelFilter = params.channel ?? null
  const filterParam = params.filter ?? null
  const searchQuery = params.q ?? null

  // Get current user for presence
  const authUser = await getAuthenticatedUser()
  const currentUserId = authUser?.user.id ?? ''
  const currentUserName = authUser?.user.full_name ?? 'Team member'

  // Resolve 'assigned-to-me' filter
  let resolvedAssignedTo: string | undefined
  if (filterParam === 'assigned-to-me') {
    resolvedAssignedTo = currentUserId || undefined
  }

  // Build filters object — only include defined optional props (exactOptionalPropertyTypes)
  const convFilters: ListConversationsFilters = {
    limit: 50,
    archived: filterParam === 'archived',
    unreadOnly: filterParam === 'unread',
  }
  if (filterParam === 'starred') convFilters.starred = true
  if (filterParam === 'resolved') convFilters.resolved = true
  if (channelFilter) {
    convFilters.channel = channelFilter as ListConversationsFilters['channel']
  }
  if (searchQuery) convFilters.search = searchQuery
  if (resolvedAssignedTo) convFilters.assignedTo = resolvedAssignedTo

  // Parallel fetch: conversation list + channel unread counts + templates + studio members
  const [listResult, unreadCounts, templates, membersResult] = await Promise.all([
    listConversations(studioId, convFilters),
    getChannelUnreadCounts(studioId),
    listMessageTemplates(studioId),
    (async (): Promise<StudioMember[]> => {
      try {
        const supabase = await createClient()
        const { data } = await supabase
          .from('studio_members')
          .select('id, user_id, role')
          .eq('studio_id', studioId)
          .is('deactivated_at', null)
        return (data ?? []) as StudioMember[]
      } catch {
        return []
      }
    })(),
  ])

  const { conversations } = listResult

  // Fetch active conversation data if c= param is set
  let activeConversation = null
  let activeMessages: Awaited<ReturnType<typeof getConversationMessages>> = []
  let conversationContext: ConversationContext | null = null
  let smartReplies: Awaited<ReturnType<typeof generateSmartReplies>> = []

  if (activeConversationId) {
    // Parallel fetch: conversation + messages + context pane data
    const [conv, msgs, ctx] = await Promise.all([
      getConversation(studioId, activeConversationId),
      getConversationMessages(studioId, activeConversationId, { limit: 50 }),
      getConversationContext(studioId, activeConversationId),
    ])

    activeConversation = conv
    activeMessages = msgs
    conversationContext = ctx

    // Mark as read if unread
    if (activeConversation && activeConversation.unread_count > 0) {
      await markConversationRead(studioId, activeConversationId)
    }

    // Generate smart replies for active conversation
    if (activeConversation && ctx) {
      const lastInbound =
        [...msgs].reverse().find((m) => m.direction === 'inbound') ?? null
      try {
        smartReplies = await generateSmartReplies({
          conversation: activeConversation,
          lastInboundMessage: lastInbound,
          upcomingBookings: ctx.upcomingBookings,
        })
      } catch {
        smartReplies = []
      }
    }
  }

  return (
    <div className="h-full flex flex-col overflow-hidden">
      <MessagesShell
        conversations={conversations}
        activeConversation={activeConversation}
        activeMessages={activeMessages}
        studioId={studioId}
        activeConversationId={activeConversationId}
        templates={templates}
        conversationContext={conversationContext}
        unreadCounts={unreadCounts}
        searchParams={params}
        currentUserId={currentUserId}
        currentUserName={currentUserName}
        members={membersResult}
        smartReplies={smartReplies}
      />
    </div>
  )
}

