// ─── fireSmartReplyAction ─────────────────────────────────────────────────────

const FireSmartReplySchema = z.object({
  conversationId: z.string().uuid(),
  action: z.discriminatedUnion('kind', [
    z.object({ kind: z.literal('send_template'), templateSlug: z.string().min(1) }),
    z.object({ kind: z.literal('open_calendar_reschedule'), bookingId: z.string().uuid() }),
    z.object({ kind: z.literal('share_portfolio') }),
    z.object({ kind: z.literal('offer_slots'), days: z.union([z.literal(1), z.literal(3), z.literal(7)]) }),
    z.object({ kind: z.literal('send_aftercare_pdf') }),
    z.object({ kind: z.literal('request_deposit') }),
  ]),
  clientId: z.string().uuid(),
  channel: z.enum(['sms', 'email']).default('sms'),
})

export async function fireSmartReplyAction(
  input: z.infer<typeof FireSmartReplySchema>,
): Promise<ActionResult<{ commId?: string | undefined; navigateTo?: string | undefined }>> {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return { ok: false, error: 'Unauthorized' }

  const parsed = FireSmartReplySchema.safeParse(input)
  if (!parsed.success) {
    return { ok: false, error: parsed.error.issues[0]?.message ?? 'Invalid input' }
  }

  const { conversationId, action, clientId, channel } = parsed.data
  const { studioId } = authUser

  try {
    // Navigation actions — return route for client-side navigation
    if (action.kind === 'open_calendar_reschedule') {
      return {
        ok: true,
        data: { navigateTo: `/calendar?rescheduleBooking=${action.bookingId}` },
      }
    }

    // Slot-offer action — render placeholder from template
    if (action.kind === 'offer_slots') {
      const templates = await listMessageTemplates(studioId, { category: 'reschedule' })
      const tpl = templates[0]
      if (!tpl) {
        return { ok: false, error: 'Reschedule template not found. Add one in Settings → Messaging.' }
      }
      const result = await sendSmsToClient(
        { studioId, clientId, body: tpl.body },
        authUser.user.id,
      )
      if (!result.ok) return { ok: false, error: result.error }
      revalidateMessages()
      return { ok: true, data: { commId: result.commId } }
    }

    // Template-based actions — map slug to send
    let templateSlug: string | null = null

    if (action.kind === 'send_template') {
      templateSlug = action.templateSlug
    } else if (action.kind === 'send_aftercare_pdf') {
      templateSlug = 'aftercare-guide'
    } else if (action.kind === 'request_deposit') {
      templateSlug = 'deposit-request'
    } else if (action.kind === 'share_portfolio') {
      templateSlug = 'portfolio-share'
    }

    if (!templateSlug) {
      return { ok: false, error: 'Unknown smart reply action' }
    }

    const templates = await listMessageTemplates(studioId)
    const tpl = templates.find((t) => t.slug === templateSlug)

    if (!tpl) {
      return { ok: false, error: `Template '${templateSlug}' not found. Check Settings → Messaging.` }
    }

    let result: Awaited<ReturnType<typeof sendSmsToClient>>

    if (channel === 'email') {
      result = await sendEmailToClient(
        { studioId, clientId, subject: tpl.name, body: tpl.body },
        authUser.user.id,
      )
    } else {
      result = await sendSmsToClient(
        { studioId, clientId, body: tpl.body },
        authUser.user.id,
      )
    }

    if (!result.ok) return { ok: false, error: result.error }

    revalidateMessages()
    return { ok: true, data: { commId: result.commId } }
  } catch (err) {
    logger.error({ err, conversationId }, 'fireSmartReplyAction: unexpected error')
    return { ok: false, error: 'Failed to send smart reply' }
  }
}

