// ─── Resolve client phone ─────────────────────────────────────────────────────

async function resolveClientPhone(
  studioId: string,
  clientId: string,
): Promise<{ phone: string } | { error: string }> {
  const supabase = createServiceRoleClient()

  const { data, error } = await supabase
    .from('clients')
    .select('phone')
    .eq('id', clientId)
    .eq('studio_id', studioId)
    .single()

  if (error || !data) {
    return { error: 'Client not found' }
  }

  if (!data.phone) {
    return { error: 'Client has no phone number on file' }
  }

  return { phone: data.phone }
}

// ─── Resolve client email ─────────────────────────────────────────────────────

async function resolveClientEmail(
  studioId: string,
  clientId: string,
): Promise<{ email: string } | { error: string }> {
  const supabase = createServiceRoleClient()

  const { data, error } = await supabase
    .from('clients')
    .select('email')
    .eq('id', clientId)
    .eq('studio_id', studioId)
    .single()

  if (error || !data) {
    return { error: 'Client not found' }
  }

  if (!data.email) {
    return { error: 'Client has no email address on file' }
  }

  return { email: data.email }
}

// ─── Upsert conversation ──────────────────────────────────────────────────────

async function upsertConversation(
  studioId: string,
  channel: 'sms' | 'email',
  externalIdentifier: string,
  clientId: string,
): Promise<string> {
  const supabase = createServiceRoleClient()

  const { data, error } = await supabase.rpc('find_or_create_conversation', {
    p_studio_id: studioId,
    p_channel: channel,
    p_external_identifier: externalIdentifier,
    p_client_id: clientId,
  })

  if (error || !data) {
    logger.error({ error, studioId, channel, externalIdentifier }, 'messaging: find_or_create_conversation failed')
    throw new Error('Failed to create conversation')
  }

  return data
}

// ─── sendSmsToClient ──────────────────────────────────────────────────────────

// ─── handleInboundSms ─────────────────────────────────────────────────────────

async function handleInboundSms(
  supabase: ReturnType<typeof createServiceRoleClient>,
  msg: { from: string; to: string; body: string; messageSid: string; params: Record<string, string> },
): Promise<void> {
  const { from, to, body, messageSid, params } = msg

  // ── 1. Resolve studio from the "To" number ──────────────────────────────────
  // Match the Twilio "To" number against studios.twilio_phone_number.
  // Falls back to TWILIO_FALLBACK_STUDIO_ID env var (for single-account setups).
  let studioId: string | null = null

  const { data: studioMatch } = await supabase
    .from('studios')
    .select('id')
    .eq('twilio_phone_number', to)
    .limit(1)
    .maybeSingle()

  studioId = studioMatch?.id ?? null

  if (!studioId) {
    studioId = process.env.TWILIO_FALLBACK_STUDIO_ID ?? null
  }

  if (!studioId) {
    logger.warn({ to }, 'twilio-webhook: could not resolve studio from To number — inbound message dropped')
    return
  }

  // ── 2. Try to match client by phone number ─────────────────────────────────
  let clientId: string | null = null

  const { data: clientMatch } = await supabase
    .from('clients')
    .select('id')
    .eq('studio_id', studioId)
    .eq('phone', from)
    .limit(1)
    .single()

  clientId = clientMatch?.id ?? null

  // ── 3. Find or create conversation ────────────────────────────────────────
  const rpcArgs: {
    p_studio_id: string
    p_channel: string
    p_external_identifier: string
    p_client_id?: string | null
  } = {
    p_studio_id: studioId,
    p_channel: 'sms',
    p_external_identifier: from,
  }
  if (clientId) rpcArgs.p_client_id = clientId

  const { data: convData, error: rpcError } = await supabase.rpc(
    'find_or_create_conversation',
    rpcArgs,
  )

  if (rpcError || !convData) {
    logger.error({ err: rpcError, from, studioId }, 'twilio-webhook: find_or_create_conversation failed')
    return
  }

  const conversationId = convData

  // ── 4. Build metadata ─────────────────────────────────────────────────────
  const mediaUrls: string[] = []
  const numMedia = parseInt(params['NumMedia'] ?? '0', 10)
  for (let i = 0; i < numMedia; i++) {
    const url = params[`MediaUrl${i}`]
    if (url) mediaUrls.push(url)
  }

  type CommMetadata = { twilio_message_sid: string; media_urls?: string[] }
  const metadataObj: CommMetadata = {
    twilio_message_sid: messageSid,
    ...(mediaUrls.length > 0 && { media_urls: mediaUrls }),
  }

  // ── 5. Insert inbound comm row ────────────────────────────────────────────
  if (!clientId) {
    // Without a client_id, we can't insert (FK constraint).
    // Log and skip — staff can link the conversation to a client manually.
    logger.warn({ from, studioId, conversationId }, 'twilio-webhook: inbound message from unknown number — no client match; message not stored in client_communications (no FK target)')
    return
  }

  const { error: insertError } = await supabase
    .from('client_communications')
    .insert({
      studio_id: studioId,
      client_id: clientId,
      conversation_id: conversationId as string,
      channel: 'sms',
      direction: 'inbound',
      body,
      status: 'delivered',
      sent_at: new Date().toISOString(),
      delivered_at: new Date().toISOString(),
      provider_message_id: messageSid,
      metadata: metadataObj as Record<string, string | string[]>,
    })

  if (insertError) {
    logger.error({ err: insertError, from, messageSid }, 'twilio-webhook: failed to insert inbound comm')
    return
  }

  logger.info({ from, studioId, conversationId, messageSid }, 'twilio-webhook: inbound SMS stored')

  // ── 6. Triage + auto-reply (post-ingest) ─────────────────────────────────
  // Wrapped in try/catch so any failure does NOT break idempotent 200 response.
  try {
    await triageConversation(studioId, conversationId as string)
  } catch (triageErr) {
    logger.error({ err: triageErr, conversationId }, 'twilio-webhook: triage failed (non-fatal)')
  }

  // Fetch the newly inserted comm id for auto-reply matching
  const { data: newComm } = await supabase
    .from('client_communications')
    .select('id')
    .eq('studio_id', studioId)
    .eq('conversation_id', conversationId as string)
    .eq('provider_message_id', messageSid)
    .single()

  if (newComm) {
    try {
      await fireAutoReplyIfMatched(studioId, conversationId as string, newComm.id)
    } catch (autoReplyErr) {
      logger.error({ err: autoReplyErr, conversationId }, 'twilio-webhook: auto-reply failed (non-fatal)')
    }
  }
}

