/**
 * useConversationContext — client-side holder for context pane data.
 *
 * v1: server-rendered context is passed as props; this hook just stores it.
 * The setter allows future realtime invalidation without prop drilling.
 */

import { useState, useEffect } from 'react'
import type { ConversationContext } from '@/lib/messaging/queries'

export function useConversationContext(
  initialContext: ConversationContext | null,
): ConversationContext | null {
  const [context, setContext] = useState<ConversationContext | null>(initialContext)

  // Sync when the server re-renders with new conversation
  useEffect(() => {
    setContext(initialContext)
  }, [initialContext])

  return context
}

