// ─── seedDefaultTemplates ─────────────────────────────────────────────────────

/**
 * Inserts default templates for a studio.
 * Idempotent — skips on (studio_id, slug) conflict.
 * Returns number of templates actually inserted.
 *
 * Uses service-role client because this is called from onboarding server action
 * where the user may not yet have a studio_member row with INSERT permissions.
 */
export async function seedDefaultTemplates(
  studioId: string,
  userId: string,
): Promise<number> {
  const supabase = createServiceRoleClient()
  let inserted = 0

  for (const tpl of DEFAULT_TEMPLATES) {
    const { error } = await supabase
      .from('message_templates')
      .insert({
        studio_id: studioId,
        slug: tpl.slug,
        name: tpl.name,
        channel: tpl.channel,
        category: tpl.category,
        body: tpl.body,
        trigger_keywords: tpl.trigger_keywords,
        is_default: tpl.is_default,
        created_by: userId,
      })
      // On conflict (studio_id, slug) — skip silently (idempotent)
      .select('id')
      .single()

    if (error) {
      // Code 23505 = unique_violation — expected for idempotent re-seed
      if ((error as { code?: string }).code !== '23505') {
        logger.warn(
          { err: error, studioId, slug: tpl.slug },
          'templates-seed: failed to insert default template',
        )
      }
      continue
    }

    inserted++
  }

  logger.info({ studioId, inserted }, 'templates-seed: default templates seeded')
  return inserted
}
